def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    serious = []
    max_prev_bid = 0.0
    cindy_like_bid = None
    for opp in alive_opponents:
        if opp.get('budget', 0) > 0:
            serious.append(opp)
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None and pbid > max_prev_bid:
            max_prev_bid = pbid
        if opp.get('daily_salary') == 70 and opp.get('water_requirement') == 13 and pbid is not None:
            if cindy_like_bid is None or pbid > cindy_like_bid:
                cindy_like_bid = pbid

    if not serious:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, 35.0))
        return float(min(budget, 5.0))

    units = supply / WATER_REQ
    if units >= 2.0:
        base = 46.0
    elif units >= 1.5:
        base = 58.0
    else:
        base = 72.0

    if cindy_like_bid is not None:
        if units < 1.5:
            base = max(base, cindy_like_bid + 3.0)
        elif units < 2.0:
            base = max(base, cindy_like_bid + 1.5)
        else:
            base = max(base, cindy_like_bid - 8.0)
    elif max_prev_bid > 0:
        base = max(base, max_prev_bid + 1.5)

    if hp <= 2 or no_water_days >= 2:
        base = max(base, 84.0)
    elif hp <= 4 or no_water_days >= 1:
        base = max(base, 68.0)

    if day >= 8 and hp > 4 and no_water_days == 0 and units >= 1.5:
        base -= 6.0

    if budget < base:
        if hp <= 2 or no_water_days >= 2:
            return float(budget)
        return float(min(budget, max(0.0, base * 0.85)))

    return float(min(budget, max(0.0, base)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents are alive, bid conservatively to save budget.
    if not alive_opponents:
        return max(0.01, min(my_budget, DAILY_SALARY * 0.4))

    # Collect yesterday's bids from all active opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Decision logic based on yesterday's highest pressure and my health
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents were very aggressive yesterday
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If I'm healthy (good HP and no recent water deprivation), try to conserve
            if my_hp > 3 and my_no_water_days == 0:
                return max(0.01, min(my_budget, DAILY_SALARY * 0.3))
            # Otherwise, I need water, so bid aggressively to survive
            return max(0.01, min(my_budget, DAILY_SALARY * 0.95))

        # If opponents were moderately aggressive or less
        # Bid slightly above the highest previous bid, or a solid moderate amount
        # Ensure it's at least 50% of salary to be competitive
        return max(0.01, min(my_budget, max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)))

    # If no previous bids are available (e.g., first day or opponents didn't bid)
    # Base strategy on my current health
    if my_hp <= 2 or my_no_water_days >= 1: # Critical health or deprived of water
        return max(0.01, min(my_budget, DAILY_SALARY * 0.9)) # Bid high to survive

    # Otherwise, I'm relatively healthy, bid moderately
    return max(0.01, min(my_budget, DAILY_SALARY * 0.55))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if 'previous_trace' in o and o['previous_trace'].get('bid') is not None]
    max_prev = max(prev_bids) if prev_bids else 0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max(max_prev + 5.0, 60.0))

    if max_prev > 50:
        return min(my_status['budget'], 55.0)

    return min(my_status['budget'], max(35.0, max_prev + 2.0))
